// Builds src/data/pdfjs-page.ts: one self-contained HTML page (pdf.js + its worker
// + a small bridge) that the app loads in a WebView to read the text out of a PDF.
// Everything is inlined so it works offline.
//
// pdf.js is pinned to 3.11.174, the last release that ships plain browser scripts
// (later versions are ES modules only). Apache-2.0 licensed; the notices stay in
// the minified files.
//
//   npm pack pdfjs-dist@3.11.174 && tar xzf pdfjs-dist-3.11.174.tgz
//   node scripts/build-pdfjs-bundle.mjs ./package [out.html]
//
// The optional out.html is the same page as a plain file, for testing in a browser.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const [pkgDir, htmlOut] = process.argv.slice(2);
if (!pkgDir) { console.error("usage: node scripts/build-pdfjs-bundle.mjs <unpacked pdfjs-dist dir> [out.html]"); process.exit(1); }

const read = (f) => fs.readFileSync(path.join(pkgDir, "legacy", "build", f), "utf8");
const version = JSON.parse(fs.readFileSync(path.join(pkgDir, "package.json"), "utf8")).version;
if (version !== "3.11.174") { console.error(`expected pdfjs-dist 3.11.174, got ${version}`); process.exit(1); }

// A literal "</script" inside the inlined source would end the tag early.
const safe = (src) => src.replace(/<\/script/gi, "<\\/script");

// Runs in the WebView after the libraries load. Reports every text run with its
// position in upright page coordinates (these reports are stored rotated 90 degrees).
const bridge = `
(function () {
  function post(o) { window.ReactNativeWebView.postMessage(JSON.stringify(o)); }
  try { pdfjsLib.GlobalWorkerOptions.workerSrc = "about:blank"; } catch (e) {}
  window.extractPdf = async function (b64) {
    try {
      var bin = atob(b64);
      var bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      var doc = await pdfjsLib.getDocument({ data: bytes, useSystemFonts: true, verbosity: 0 }).promise;
      var items = [];
      for (var n = 1; n <= doc.numPages; n++) {
        var page = await doc.getPage(n);
        var vp = page.getViewport({ scale: 1 });
        var tc = await page.getTextContent();
        for (var k = 0; k < tc.items.length; k++) {
          var it = tc.items[k];
          if (typeof it.str !== "string") continue;
          var t = pdfjsLib.Util.transform(vp.transform, it.transform);
          items.push({ s: it.str, x: Math.round(t[4] * 100) / 100, y: Math.round(t[5] * 100) / 100, w: Math.round(it.width * 100) / 100, page: n });
        }
      }
      post({ type: "items", items: items });
    } catch (e) {
      post({ type: "error", message: String((e && e.message) || e) });
    }
  };
  post({ type: "ready" });
})();
`;

const html =
  '<!doctype html><html><head><meta charset="utf-8"></head><body>' +
  "<script>" + safe(read("pdf.min.js")) + "</script>" +
  "<script>" + safe(read("pdf.worker.min.js")) + "</script>" +
  "<script>" + bridge + "</script>" +
  "</body></html>";

const here = path.dirname(fileURLToPath(import.meta.url));
const out = path.join(here, "..", "src", "data", "pdfjs-page.ts");
fs.writeFileSync(
  out,
  "// Generated by scripts/build-pdfjs-bundle.mjs from pdfjs-dist 3.11.174 (Apache-2.0). Do not edit.\n" +
    "export const PDFJS_PAGE_HTML = " + JSON.stringify(html) + ";\n",
);
console.log(`wrote ${path.relative(process.cwd(), out)} (${(html.length / 1048576).toFixed(2)} MB of HTML)`);
if (htmlOut) { fs.writeFileSync(htmlOut, html); console.log(`wrote ${htmlOut}`); }
